#!/usr/bin/env bash
set -Eeuo pipefail
TMP="$(mktemp -d)"
trap 'true' EXIT
base64 -d > "$TMP/pack.tar.gz" <<'PAYLOAD'

PAYLOAD
tar --no-same-owner -xzf "$TMP/pack.tar.gz" -C "$TMP"
case "${1:-install}" in
  repair) shift; exec bash "$TMP/repair.sh" "$@" ;;
  install) exec bash "$TMP/install.sh" "$@" ;;
  *) echo "usage: sudo bash agent2agent_v1_2.sh [install|repair]"; exit 2 ;;
esac
